mapper.update:
update club_lead_state
leader_member_id = #{leaderMemberId}, current_chapter_id = #{currentChapterId}, broadcast_text = #{broadcastText}, broadcast_at = #{broadcastAt}, status = #{status},
where id = #{id}

mapper.select:
select id, activity_id, member_id, arrived_at
from club_lead_checkin where activity_id = #{activityId}
order by arrived_at asc

select cls.id as stateId, cls.activity_id as activityId, cls.status as runStatus, cls.leader_member_id as leaderMemberId, lm.nickname as leaderName, cls.current_chapter_id as currentChapterId, cls.broadcast_text as broadcastText, cls.broadcast_at as broadcastAt, cls.create_time as createTime, ca.name as activityName, ca.address_name as addressName, ca.address as address, ca.start_date as startDate, ca.club_id as clubId, cb.name as clubName, ca.topic_id as topicId, t.name as topicName, (select count(*) from cms_registration r where r.owner_type = 2 and r.owner_id = ca.id and r.payment_status = 2) as regCount, (select count(*) from club_lead_checkin ck where ck.activity_id = ca.id) as checkinCount from club_lead_state cls join cms_activity ca on ca.id = cls.activity_id left join cms_topic t on t.id = ca.topic_id left join club cb on cb.id = ca.club_id left join ums_member lm on lm.id = cls.leader_member_id
and ca.topic_id = #{topicId} and ca.club_id = #{clubId} and cls.status = #{status}
order by cls.create_time desc
